INSERT INTO `categories` VALUES (1,'วัสดุ(Supplies)','เป็นของใช้ที่เมื่อใช้งานแล้วจะสิ้นเปลืองไป หรือมีการเปลี่ยนแปลงสภาพไปในระยะเวลาอันสั้น มักมีราคาย่อมเยา และมีการใช้งานบ่อยครั้ง','active','2025-08-15 04:09:58','2025-08-15 04:09:58'),(2,'ครุภัณฑ์ (Equipment)','เป็นของใช้ที่มีลักษณะคงทนถาวร มีอายุการใช้งานยาวนาน มักมีราคาสูง และไม่สิ้นเปลืองง่าย เช่น เตียงผู้ป่วย, เครื่องมือแพทย์, เครื่องเอกซเรย์, เครื่องมือผ่าตัด, รถเข็นผู้ป่วย, ตู้เย็น, โต๊ะทำงาน, เก้าอี้, คอมพิวเตอร์','active','2025-08-15 04:10:29','2025-08-15 04:10:29'),(3,'เวชภัณฑ์ที่ไม่ใช่ยา (Medical non-drug supplies)','เวชภัณฑ์ที่ไม่ใช่ยา (Medical non-drug supplies) หมายถึง วัสดุอุปกรณ์ต่างๆ ที่ใช้ในทางการแพทย์ แต่ไม่ใช่ยา เช่น วัสดุการแพทย์ วัสดุทันตกรรม วัสดุวิทยาศาสตร์การแพทย์ วัสดุเอกซเรย์ รวมถึงอุปกรณ์ทางการแพทย์ต่างๆ ที่ใช้กับผู้ป่วยเฉพาะราย.','active','2025-08-15 04:12:26','2025-08-15 04:12:26'),(4,'ยา (drug)','ยา คือ สารหรือสารเคมีที่ออกฤทธิ์ต่อร่างกาย ทำให้มีผลในการ\r\nป้องกันโรค   ส่งเสริมสุขภาพ  บำบัด บรรเทา รักษาโรค  วินิจฉัยโรค','active','2025-08-19 02:02:58','2025-08-20 02:59:03');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

