INSERT INTO `departments` VALUES (1,'แผนกอุบัติเหตุและฉุกเฉิน (ER)','แผนกฉุกเฉิน (อังกฤษ: emergency department) หรือเรียก แผนกอุบัติเหตุและฉุกเฉิน (อังกฤษ: accident & emergency department), ห้องฉุกเฉิน (อังกฤษ: emergency room), หอผู้ป่วยฉุกเฉิน (อังกฤษ: emergency ward) หรือแผนกอุบัติเหตุ (อังกฤษ: casualty department) เป็นสถานบริการทางการแพทย์ที่มีความชำนาญพิเศษด้านเวชศาสตร์ฉุกเฉิน หมายถึง การบริบาลแบบฉับพลันซึ่งผู้ป่วยที่มาโดยมิได้นัดล่วงหน้า','active','2025-08-15 01:54:45','2025-08-15 01:54:45'),(2,'แผนกผู้ป่วยนอก (OPD)','OPD ย่อมาจาก Out-Patient Department หรือแผนกผู้ป่วยนอก ในโรงพยาบาล. หมายถึง การเข้ารับการรักษาที่โรงพยาบาลแล้วไม่ต้องนอนพักรักษาตัว. ผู้ป่วยสามารถรับการตรวจ, รักษา, และรับยา แล้วสามารถกลับบ้านได้เลย. มักใช้กับอาการเจ็บป่วยที่ไม่รุนแรง เช่น ไข้หวัด, อาการแพ้, หรืออุบัติเหตุเล็กน้อย.','active','2025-08-15 01:56:31','2025-08-15 01:56:31'),(3,'แผนกคลินิกทันตกรรม(dental department)','แผนกทันตกรรม (Dental Department) หรือ ศูนย์ทันตกรรม (Dental Center) เป็นหน่วยงานภายในโรงพยาบาลหรือคลินิกที่ให้บริการเกี่ยวกับการดูแลสุขภาพช่องปากและฟัน โดยมีทันตแพทย์และบุคลากรทางการแพทย์ที่เชี่ยวชาญในการตรวจ วินิจฉัย และรักษาโรคทางทันตกรรมต่างๆ การตรวจสุขภาพฟัน, การขูดหินปูน, การอุดฟัน, การถอนฟัน, การเคลือบฟลูออไร,ให้บริการศัลยกรรมผ่าฟันคุด','active','2025-08-15 01:58:41','2025-08-15 02:00:30'),(4,'แผนกห้องปฏิบัติการทางการแพทย์ (LAB)','ห้องปฏิบัติการทางการแพทย์:\r\nโดยเฉพาะในบริบททางการแพทย์ ห้องแล็บ หรือห้องปฏิบัติการ จะเป็นส่วนหนึ่งของโรงพยาบาลหรือคลินิก ที่ใช้ในการตรวจวิเคราะห์ตัวอย่างทางการแพทย์ เช่น เลือด ปัสสาวะ หรือเนื้อเยื่อ เพื่อช่วยในการวินิจฉัยโรค ติดตามอาการ หรือประเมินผลการรักษา.','active','2025-08-15 02:38:50','2025-08-15 02:38:50'),(5,'แผนกเภสัชกรรม( Pharmacy Department)','แผนกเภสัชกรรม (Pharmacy Department) คือ แผนกที่ให้บริการเกี่ยวกับการใช้ยาและการจัดการยาในโรงพยาบาลหรือสถานพยาบาล. หน้าที่หลักของแผนกเภสัชกรรมคือ การจัดหายาและเวชภัณฑ์, การจ่ายยาให้ผู้ป่วยตามใบสั่งแพทย์, การให้คำแนะนำการใช้ยาแก่ผู้ป่วย, และการควบคุมคุณภาพของยาที่ใช้ในโรงพยาบาล','active','2025-08-15 02:40:28','2025-08-15 02:40:28'),(6,'แผนกหน่วยจ่ายกลาง (Central Sterile Supply Department หรือ CSSD)','แผนกหน่วยจ่ายกลาง (Central Sterile Supply Department หรือ CSSD) เป็นหน่วยงานสำคัญในโรงพยาบาลที่มีหน้าที่รับผิดชอบในการทำความสะอาด ฆ่าเชื้อ และทำให้เครื่องมือแพทย์ปราศจากเชื้อ เพื่อนำกลับมาใช้ใหม่ได้อย่างปลอดภัย. หน่วยจ่ายกลางทำหน้าที่เป็นศูนย์กลางในการรวบรวมเครื่องมือที่ใช้แล้ว นำมาผ่านกระบวนการทำความสะอาด ฆ่าเชื้อ และบรรจุหีบห่อ ก่อนจะแจกจ่ายไปยังหน่วยงานต่างๆ ภายในโรงพยาบาล.','active','2025-08-15 02:41:32','2025-08-15 02:41:32'),(7,'ศูนย์ชีวาภิบาลพบโชคเปี่ยมสุข(Pobchock cheewabhibaln palliative care center)','ศูนย์ชีวาภิบาลในโรงพยาบาล หมายถึง ศูนย์ที่จัดตั้งขึ้นเพื่อสร้างระบบชีวาภิบาลในโรงพยาบาล  โดยบูรณาการระบบริการดูแลผู้สูงอายุ (Elderly Care) การดูแลระยะยาว (Long-Term Care) การดูแล ประคับประคอง/ระยะท้าย (Palliative Care) และเชื่อมโยงระบบบริการปฐมภูมิ (Primary Health Care) ตั้งแต่ การดูแลในโรงพยาบาลจนถึงบ้าน/ชุมชน','active','2025-08-15 02:58:08','2025-08-15 02:58:08'),(8,'แผนก X-ray หรือแผนกรังสีวินิจฉัย (Radiology Department)','แผนก X-ray หรือแผนกรังสีวินิจฉัย (Radiology Department) เป็นแผนกในโรงพยาบาลหรือสถานพยาบาลที่ให้บริการตรวจวินิจฉัยโรคโดยใช้เทคโนโลยีรังสีต่างๆ เช่น รังสีเอกซ์ (X-ray), การตรวจด้วยคลื่นแม่เหล็กไฟฟ้า (MRI), การตรวจด้วยคลื่นเสียงความถี่สูง (Ultrasound), และการเอกซเรย์คอมพิวเตอร์ (CT scan) เพื่อสร้างภาพอวัยวะภายในร่างกาย. ภาพเหล่านี้ช่วยให้แพทย์สามารถมองเห็นโครงสร้างภายในร่างกายและวินิจฉัยโรคต่างๆ ได้อย่างถูกต้องและแม่นยำ.','active','2025-08-15 03:01:32','2025-08-15 03:01:32'),(9,'แผนกแม่บ้านโรงพยาบาล(Housekeeping department in the hospital)','แผนกแม่บ้านในโรงพยาบาลมีหน้าที่หลักในการรักษาความสะอาดและสุขอนามัยของโรงพยาบาล เพื่อสร้างสภาพแวดล้อมที่ปลอดภัยและเอื้อต่อการรักษาพยาบาลของผู้ป่วย. พวกเขาทำความสะอาดและฆ่าเชื้อพื้นที่ต่างๆ เช่น ห้องพักผู้ป่วย ห้องน้ำ พื้นที่ส่วนกลาง รวมถึงการจัดการขยะและผ้าปูที่นอน. การทำงานของแผนกแม่บ้านมีความสำคัญอย่างยิ่งต่อการควบคุมการติดเชื้อและสร้างความมั่นใจให้กับผู้ป่วยและบุคลากรทางการแพทย์.','active','2025-08-15 03:49:39','2025-08-15 03:49:39'),(10,'แผนกโภชนาการ(Nutrition department)','แผนกโภชนาการในโรงพยาบาล (แผนกโภชนวิทยา หรือ ฝ่ายโภชนาการ) มีหน้าที่หลักในการดูแลด้านโภชนาการของผู้ป่วยและผู้รับบริการอื่นๆ ในโรงพยาบาล โดยมีเป้าหมายเพื่อให้ได้รับอาหารที่ถูกต้อง เหมาะสมกับโรค ปลอดภัย สะอาด และมีคุณภาพ รวมถึงให้คำปรึกษาด้านโภชนาการแก่ผู้ป่วยและญาติ.','active','2025-08-15 03:51:57','2025-08-15 03:51:57'),(11,'แผนกคลังสินค้า( Main store)','แผนกคลังสินค้า( Main store): บริหารจัดการเก็บสินค้า รับเข้า-ส่งออก สินค้า วัสดุต่างๆ','active','2025-08-15 06:22:43','2025-08-15 06:22:43');
