INSERT INTO `product_types` VALUES (1,'วัสดุสิ้นเปลืองทั่วไป (Consumables)','วัสดุสิ้นเปลืองทั่วไป (Consumables): เช่น   ถุงมือ, หน้ากากอนามัย, ผ้าก๊อซ, สำลี, น้ำยาทำความสะอาด, ถังขยะ','active','2025-08-15 04:14:17','2025-08-15 06:16:01'),(2,'วัสดุทางการแพทย์ (Medical Supplies)','วัสดุทางการแพทย์ (Medical Supplies): เช่น เข็มฉีดยา, กระบอกฉีดยา, สายน้ำเกลือ, ถุงมือ, หลอดเก็บเลือด, ชุดทำแผล, เวชภัณฑ์ต่างๆ','active','2025-08-15 04:14:46','2025-08-15 04:14:46'),(3,'วัสดุวิทยาศาสตร์ (Scientific Supplies)','วัสดุวิทยาศาสตร์ (Scientific Supplies): เช่น สารเคมี, หลอดทดลอง, อุปกรณ์วิเคราะห์, สัตว์ทดลอง','active','2025-08-15 04:15:13','2025-08-15 04:15:13'),(4,'วัสดุสำนักงาน (Stationery)','วัสดุสำนักงาน (Stationery): เช่น กระดาษ, ปากกา, ดินสอ, แฟ้ม, สมุด, คลิปหนีบกระดาษ','active','2025-08-15 04:15:48','2025-08-15 04:15:48'),(5,'วัสดุอื่นๆ','วัสดุอื่นๆ: เช่น น้ำมัน, น้ำยาหล่อลื่น, อะไหล่เครื่องจักร, วัสดุทำความสะอาด, วัสดุสำหรับงานบ้านงานครัว','active','2025-08-15 04:26:09','2025-08-15 04:26:09'),(6,'วัสดุทันตกรรม (Dental supply)','วัสดุทันตกรรมมีหลากหลายประเภท ขึ้นอยู่กับลักษณะการใช้งานและจุดประสงค์ในการรักษา โดยทั่วไปสามารถแบ่งได้เป็น:1. วัสดุอุดฟัน:2. วัสดุครอบฟัน/สะพานฟัน:3. วัสดุสำหรับงานทันตกรรมประดิษฐ์:5. เครื่องมือทางทันตกรรม:','active','2025-08-15 04:29:52','2025-08-15 04:29:52'),(7,'วัสดุเอกซเรย์ (X-ray supply)','วัสดุที่ใช้ในการถ่ายภาพรังสีมีหลายประเภท โดยหลักๆ สามารถแบ่งได้เป็นวัสดุที่ใช้ในการสร้างภาพและวัสดุที่ใช้ป้องกันรังสี.','active','2025-08-15 04:31:24','2025-08-15 04:31:24'),(8,'วัสดุเภสัชกรรม (Pharmacy supply)','วัสดุเภสัชกรรม (Pharmacy Supplies) หมายถึง อุปกรณ์และวัสดุต่างๆ ที่ใช้ในร้านขายยาและสถานพยาบาล เพื่อใช้ในการเตรียมยา จ่ายยา และให้บริการด้านเภสัชกรรมอื่นๆ','active','2025-08-15 04:34:25','2025-08-15 04:34:25'),(9,'กลุ่มยาปฎิชีวนะ (antibiotic drug)','ยาฆ่าเชื้อ (Antibiotics) คือ ยาที่ใช้ในการรักษาโรคติดเชื้อแบคทีเรีย โดยมีฤทธิ์ในการฆ่าเชื้อแบคทีเรียหรือยับยั้งการเจริญเติบโตของแบคทีเรีย','active','2025-08-19 02:04:44','2025-08-20 07:23:55'),(10,'กลุ่มยาแก้ปวด+ลดการอักเสบ  NSAIDs (Nonsteroidal Anti-inflammatory Drugs)','ยาแก้ปวดลดการอักเสบ คือ ยาที่ใช้ลดอาการปวด บวม แดง ร้อน ซึ่งเป็นอาการที่เกิดจากการอักเสบของร่างกาย NSAIDs หรือยาต้านการอักเสบที่ไม่ใช่สเตียรอยด์ (Nonsteroidal Anti-inflammatory Drugs) เป็นยาที่ใช้เพื่อบรรเทาอาการปวด ลดไข้ และลดการอักเสบ.','active','2025-08-19 03:13:32','2025-08-20 07:24:08'),(11,'กลุ่มยาฆ่าเชื้อรา(antifungal/antimycotic drug)','ยาต้านเชื้อราหรือที่รู้จักกันในชื่อยาต้านเชื้อรา (antimycotic drug ) เป็นยาฆ่าเชื้อราหรือ ยา ต้านเชื้อราชนิดออกฤทธิ์ต่อจิตประสาท ใช้รักษาและป้องกันโรคติดเชื้อราเช่น โรค น้ำกัดเท้า โรคกลากโรคติด เชื้อแคนดิดา (โรคปากนกกระจอก) โรคติดเชื้อระบบร้ายแรง เช่นโรคเยื่อหุ้มสมอง อักเสบจากเชื้อ คริปโตค็อกคัส และอื่นๆ','active','2025-08-20 07:26:55','2025-08-20 07:26:55'),(12,'กลุ่มยาต้านภูมิแพ้(Antihistamine drug)','าแก้แพ้ หรือ ยาแอนติฮิสตามีน เป็นกลุ่มยาที่มีโครงสร้างคล้ายสารฮิสตามีน (Histamine) ที่เมื่อรับประทานยาเข้าไปแล้ว ยาจะเข้าไปจับกับตัวจับ/ตัวรับของสารฮิสตามีน (Histamine receptor) ที่อยู่บนผิวของเนื้อเยื่อตามระบบหายใจ เช่น ในโพรงจมูก หลอดลม ถุงลม และตามผิว หนังต่างๆ แทนตัวสารฮิสตามีน จึงทำให้ฮิสตามีนเข้าไปจับกับตัวรับของมันไม่ได้ จึงทำให้ไม่เกิดอาการที่เป็นผลจากกระบวนการแพ้ทั้งหลาย ดังนั้น ยากลุ่มนี้จึงนำมาใช้รักษาอาการที่เกิดจากกระ บวนการแพ้หรือโรคภูมิแพ้นั่นเอง','active','2025-08-20 07:28:56','2025-08-20 07:28:56'),(13,'กลุ่มยาแก้ไอ+ละลายเสมหะ(Antitussives/Expectorants drugs)','ยาแก้ไอขับเสมหะ มีหลายประเภทที่ออกฤทธิ์แตกต่างกันไป โดยทั่วไปแล้วยาแก้ไอจะแบ่งเป็น 2 กลุ่มใหญ่ๆ คือ ยาแก้ไอ (Antitussives) ซึ่งมีฤทธิ์ระงับอาการไอ และยาขับเสมหะ (Expectorants) ซึ่งช่วยขับเสมหะออกจากระบบทางเดินหายใจ','active','2025-08-20 07:31:06','2025-08-20 07:31:06'),(14,'กลุ่มยาลดกรด+ขับลม+ท้องอืด (antacids/antiflatulents drugs)','ยาที่ใช้ลดกรดและขับลมส่วนใหญ่จะออกฤทธิ์ช่วยลดปริมาณกรดในกระเพาะอาหารและช่วยขับลมในระบบทางเดินอาหาร ทำให้บรรเทาอาการท้องอืด ท้องเฟ้อ และแสบร้อนกลางอกได้ ยาเหล่านี้มีทั้งแบบที่เป็นยาลดกรด (antacids) และยาขับลม (antiflatulents) ซึ่งอาจมีตัวยาที่ออกฤทธิ์ร่วมกัน หรือใช้ร่วมกันเพื่อเพิ่มประสิทธิภาพในการรักษา.','active','2025-08-20 07:38:46','2025-08-20 07:39:48'),(15,'กลุ่มยาแก้ปวด บิดท้อง (antispasmodics drugs)','ยาที่ใช้ลดอาการปวดท้องบิดเกร็ง มักเป็นยากลุ่มที่ออกฤทธิ์คลายกล้ามเนื้อเรียบ (antispasmodics) ซึ่งช่วยลดการบีบตัวของกล้ามเนื้อในระบบทางเดินอาหาร. ยาเหล่านี้จะช่วยลดอาการปวดเกร็งที่เกิดจากการบีบตัวของกล้ามเนื้อในกระเพาะอาหาร ลำไส้ และอวัยวะอื่น ๆ ในช่องท้อง.','active','2025-08-20 07:41:33','2025-08-20 07:41:33'),(16,'กลุ่มยาแก้วิงเวียนศีรษะ (Anti-dizziness drugs)','กลุ่มยาแก้วิงเวียนศีรษะ (Anti-dizziness drugs)ยาแก้เวียนหัวที่ใช้กันทั่วไปมีหลายชนิด เช่น ยาเม็ด Dimenhydrinate (ไดเมนไฮดริเนต) ที่ใช้แก้อาการเมารถ เมาเรือ และอาการเวียนศีรษะ นอกจากนี้ยังมี Cinnarizine (ซินนาริซีน) ที่ใช้รักษาอาการเวียนศีรษะและป้องกันไมเกรน และ Betahistine (เบตาฮีสทีน) ที่ใช้รักษาอาการเวียนศีรษะจากโรคหูชั้นใน','active','2025-08-20 07:44:13','2025-08-20 07:44:13'),(17,'กลุ่มยาคลายกล้ามเนื้อ(Muscle Relaxant drugs)','กลุ่มยาคลายกล้ามเนื้อ(Muscle Relaxant drugs) เป็นกลุ่มยาที่ออกฤทธิ์ลดการเกร็งตัวของกล้ามเนื้อ ช่วยบรรเทาอาการปวดเมื่อย กล้ามเนื้อกระตุก หรืออาการตึงของกล้ามเนื้อ. ยาเหล่านี้มักใช้รักษาอาการปวดกล้ามเนื้อเฉียบพลันที่เกิดจากการใช้งานหนัก หรืออยู่ในท่าทางที่ไม่เหมาะสมเป็นเวลานาน.','active','2025-08-20 07:46:03','2025-08-20 07:46:03'),(18,'กลุ่มยาแก้ปวด+ลดไข้ (antipyretic drugs)','ยาแก้ปวดลดไข้ หรือยา antipyretic เป็นกลุ่มยาที่ใช้เพื่อลดไข้และบรรเทาอาการปวด ยาในกลุ่มนี้ที่ใช้บ่อย ได้แก่ พาราเซตามอล','active','2025-08-20 07:48:42','2025-08-20 07:48:42'),(19,'กลุ่มยาแก้คลื่นไส้ อาเจียน(Antiemetic drugs)','ข้อมูลภาพรวมโดย AI\r\nยาแก้อาเจียน (Antiemetic drugs) เป็นยาที่ใช้รักษาอาการคลื่นไส้และอาเจียน โดยออกฤทธิ์ยับยั้งการทำงานของสารสื่อประสาทที่เกี่ยวข้องกับการอาเจียน ยาเหล่านี้มีหลายกลุ่ม แต่ละกลุ่มมีกลไกการออกฤทธิ์ที่แตกต่างกันไป','active','2025-08-20 07:50:11','2025-08-20 07:50:11'),(20,'กลุ่มยาระบาย,ยาถ่ายพยาธิ(laxatives,Anthelmintics drugs)','ยาระบายชนิดกระตุ้นการทำงานของลำไส้ (stimulant laxatives) ยาระบาย (Laxative Drug) คือกลุ่มยาที่ใช้รักษาอาการท้องผูก โดยยาระบายจะออกฤทธิ์กระตุ้นการทำงานของลำไส้ หรืออาจเพิ่มความอ่อนนุ่มให้อุจจาระ ทำให้อุจจาระเคลื่อนตัวได้สะดวกและง่ายต่อการขับถ่าย ทั้งนี้ ก่อนใช้ยาระบายควรปรึกษาแพทย์หรือเภสัชกร เพื่อความปลอดภัยในการใช้ยา/ยาถ่ายพยาธิ หรือ ยาต้านพยาธิ เป็นกลุ่ม ยาที่ขับพยาธิ ออกจากร่างกาย โดยทำให้พยาธิ ( helminths ) และปรสิตภายในอื่นๆ','active','2025-08-20 07:55:33','2025-08-20 07:55:33'),(21,'กลุ่มยาต้านไวรัส (antiviral agent/drugs)','กลุ่มยาต้านไวรัส (antiviral agent/drugs) คือ ยาที่ใช้รักษาหรือป้องกันการติดเชื้อไวรัส โดยยาเหล่านี้จะออกฤทธิ์เฉพาะต่อไวรัส ซึ่งแตกต่างจากยาปฏิชีวนะที่ใช้รักษาการติดเชื้อแบคทีเรีย ยาต้านไวรัสทำงานโดยการขัดขวางวงจรชีวิตของไวรัส เช่น การจำลองตัวเอง หรือการเข้าสู่เซลล์เจ้าบ้าน','active','2025-08-20 07:57:39','2025-08-20 07:57:39'),(22,'กลุ่มยาสมุนไพร (HERBS)','Herbal medicineหรือยาจากสมุนไพร คือ กลุ่มสารสําคัญที่ได้จากส่วนประกอบของพืชเช่น ใบ ราก ดอก หรือส่วนต่างๆจากต้น ทั่วโลกมีการผลิตสารในกลุ่มนี้จากพืช ประมาณ 40,000 ถึง 50,000 ชนิด โดยวิธีดั้งเดิมและ วิธีทันสมัย มีเพียงส่วนน้อยที่มีข้อมูลทางวิทยาศาสตร์ที่เป็นข้อมูลรองรับคุณสมบัติ แต่อย่างไรก็ตามสารที่ได้จาก ธรรมชาติ','active','2025-08-20 08:00:36','2025-08-20 08:00:36'),(23,'กลุ่มยาบำรุงกระดูก(Bone anabolic agents)','กลุ่มยาบำรุงกระดูก หมายถึง ยาและผลิตภัณฑ์เสริมอาหารที่ช่วยเสริมสร้างและบำรุงกระดูกให้แข็งแรง ป้องกันการเกิดภาวะกระดูกพรุน และลดความเสี่ยงต่อการเกิดกระดูกหัก ซึ่งส่วนใหญ่จะประกอบด้วยแคลเซียมและวิตามินดีเป็นหลัก.','active','2025-08-20 08:02:50','2025-08-20 08:02:50'),(24,'กลุ่มยาบำรุงโลหิต','ยาบำรุงเลือด คือ กลุ่มยาที่ช่วยเสริมธาตุเหล็กและสารอาหารที่จำเป็นต่อการสร้างเม็ดเลือดแดงในร่างกาย. ยาเหล่านี้มักใช้รักษาหรือป้องกันภาวะโลหิตจางจากการขาดธาตุเหล็ก หรือภาวะที่ร่างกายเสียเลือดมาก เช่น ผู้หญิงที่มีประจำเดือนมามากผิดปกติ.','active','2025-08-20 08:09:39','2025-08-20 08:09:39'),(25,'กลุ่มยาวิตามิน (Vitamins)','ลุ่มยาวิตามิน หมายถึง กลุ่มของสารอาหารที่จำเป็นต่อร่างกาย ซึ่งร่างกายต้องการในปริมาณน้อย แต่ก็ขาดไม่ได้เพราะมีส่วนสำคัญในการทำงานของระบบต่างๆ ในร่างกาย วิตามินแบ่งออกเป็น 2 กลุ่มใหญ่ๆ ตามคุณสมบัติในการละลาย คือ วิตามินที่ละลายในน้ำ และ วิตามินที่ละลายในไขมัน','active','2025-08-20 08:18:54','2025-08-20 08:18:54'),(26,'กลุ่มยาลดความดันโลหิต (anti-Hypertensive drugs)','ยาลดความดันโลหิต สามารถแบ่งออกได้เป็น 5 กลุ่มหลัก ได้แก่ กลุ่ม Angiotensin Converting Enzyme Inhibitors (ACEIs), Angiotensin Receptor Blockers (ARBs), Beta-Blockers, Calcium-Channel Blockers (CCBs) และยาขับปัสสาวะ ซึ่งผู้ใช้ยาลดความดันควรรู้จักชนิดของยาที่รับประทานและอาการข้างเคียงของยาที่อาจจะเกิดขึ้น เพื่อให้เกิดความปลอดภัยในขณะใช้ยา และสามารถแจ้งข้อมูลกับแพทย์ได้อย่างถูกต้องหากเกิดปัญหาหรือข้อสงสัยระหว่างการใช้ยา','active','2025-08-20 08:19:11','2025-08-20 08:21:02'),(27,'กลุ่มยาใช้ภายนอก/ยาทา ยาป้าย','การใช้ยาที่ใช้ภายนอก ยาที่ใช้ภายนอกได้แก่ ขี้ผึ้ง ครีม ยาผง ยาเหน็บ ยาหยอด มีข้อดีคือยาจะมีผลเฉพาะบริเวณที่ให้ยาเท่านั้นและมีการดูดซึมเข้าสู่ร่างกายได้น้อย จึงไม่ค่อยมีผลอื่นต่อระบบในร่างกาย ข้อเสียคือ ใช้ได้ดีกับโรคที่เกิดบริเวณพื้นผิวร่างกายเท่านั้น','active','2025-08-20 08:31:20','2025-08-20 08:31:20'),(28,'กลุ่มยาหยอดตา/หู (Eye /Ear drops)','ยาหยอดตาและยาหยอดหู เป็นยาที่ใช้สำหรับหยอดบริเวณดวงตาและช่องหูตามลำดับ เพื่อรักษาอาการผิดปกติที่เกิดขึ้นบริเวณดังกล่าว ยาหยอดตาใช้รักษาอาการทางตา เช่น การติดเชื้อ การอักเสบ หรืออาการแพ้ ส่วนยาหยอดหูใช้รักษาอาการในช่องหู เช่น การติดเชื้อ การอักเสบ หรือการอุดตันของขี้หู.','active','2025-08-20 08:33:03','2025-08-20 08:33:03'),(29,'กลุ่มยาอื่นๆที่ใช้บ่อย-ขอบ่อย','ยาอื่นๆเช่น ยาดม ยาหอม ยาปะปวด.','active','2025-08-20 08:34:17','2025-08-20 08:34:17'),(30,'กลุ่มยาเหน็บ ต่างๆ','กลุ่มยาเหน็บ ต่างๆ เช่น ยาเหน็บช่องคลอด/ยาเหน็บทวาร','active','2025-08-20 08:35:15','2025-08-20 08:35:15'),(31,'กลุ่มยาฉีดปฏิชีวนะ (Antibiotic injection)','กลุ่มยาฉีดปฏิชีวนะ (Antibiotic injection) คือ ยาที่ใช้รักษาการติดเชื้อแบคทีเรีย โดยมีรูปแบบเป็นยาฉีด ซึ่งจะออกฤทธิ์ฆ่าเชื้อแบคทีเรียหรือยับยั้งการเจริญเติบโตของแบคทีเรีย ยาเหล่านี้จะถูกฉีดเข้าสู่ร่างกายทางหลอดเลือดดำ หรือกล้ามเนื้อ โดยแพทย์หรือผู้เชี่ยวชาญ','active','2025-08-20 08:37:58','2025-08-20 08:37:58'),(32,'กลุ่มยาฉีดทั่วไป ทั้งหมด','กลุ่มยาฉีดทั่วไป เช่น ยาฉีดรวมๆทั้งหมด ยกเว้นยาปฏิชีวนะ','active','2025-08-20 08:39:10','2025-08-20 08:39:10'),(33,'ยาชาในหัตถการเล็ก (Local anesthetics)','ยาชาเฉพาะที่ (Local anesthetics) เป็นยาใช้ระงับความรู้สึกเฉพาะที่ ออกฤทธิ์ยับยั้งการกระตุ้นปลายประสาทรับความรู้สึก (Nerve ending) หรือโดยการขัดขวางการส่งสัญญาณประสาทไปยังระบบประสาทส่วนปลายที่ทำให้รับรู้ความรู้สึกที่อยู่ในบริเวณผิวหนังและเยื่อบุต่างๆ ของร่างกาย แต่ยาชาเฉพาะที่ไม่ได้มีผลทำให้เกิดอาการชาที่ส่วนอื่นๆ ของ','active','2025-08-20 08:40:15','2025-08-20 08:40:15'),(34,'วัคซีนต่างๆ(vaccines)','วัคซีนต่างๆ เช่น DT/TT/PCEC/ERIG/HB vaccines','active','2025-08-20 08:41:18','2025-08-20 08:41:18'),(35,'กลุ่มยาสเตียรอยด์ (Steroids)','เนื่องด้วยคุณสมบัติในการรักษาของสารสเตียรอยด์มีมากมายนั่นเอง จึงทำให้บริษัทผลิตยา ผลิตยาสเตียรอยด์ขึ้นมาจำหน่ายโดยเลียนแบบสเตียรอยด์ที่ร่างกายสร้างขึ้น เพื่อใช้ในการรักษาทางการแพทย์ เป็นยาเคมี ที่ให้ผลในเรื่องการรักษาโรคได้ดีและรวดเร็วคล้ายสเตียรอยด์ธรรมชาติ แต่แตกต่างกัน ตรงที่สเตียรอยด์เป็นยาเคมีสังเคราะห์ และมีผลข้างเคียงที่เป็นอันตรายมากกว่า มีฤทธิ์กดภูมิคุ้มกัน มีหลายชนิดแต่ชนิดที่เรามักจะได้ยินคุ้นหู คือ เดกซาเมธาโซน และเพรดนิโซโลน','active','2025-08-20 08:44:11','2025-08-20 08:44:11'),(36,'กลุ่มยาจิตเวช (antipsychotic drugs)','Antipsychotics หรือยาต้านอาการทางจิต เป็นยาที่ออกฤทธิ์ยับยั้งตัวรับสารสื่อประสาทโดพามีน อาจนำมาใช้เพียงชั่วคราวหรือในระยะยาวเพื่อลดอาการที่เกิดจากภาวะทางจิต อย่างการเห็นภาพหลอน หลงผิด หูแว่ว รวมถึงอาจนำมาใช้ร่วมกับยาชนิดอื่นเพื่อรักษาภาวะสมาธิสั้น พฤติกรรมการรับประทานอาหารผิดปกติ ความเครียด','active','2025-08-20 08:46:50','2025-08-20 08:46:50'),(37,'กลุ่มยาเสี่ยงสูง HAD (High Alert Drugs)','กลุ่มยาเสี่ยงสูง (High Alert Drugs หรือ HAD) คือ กลุ่มยาที่มีความเสี่ยงสูงที่จะก่อให้เกิดอันตรายร้ายแรงต่อผู้ป่วย หากมีการใช้ยาผิดพลาดหรือมีการบริหารยาที่ไม่ถูกต้อง. เนื่องจากยาเหล่านี้มีช่วงการรักษาแคบ (narrow therapeutic index) หรือมีผลข้างเคียงที่รุนแรงต่ออวัยวะสำคัญของร่างกาย เช่น สมอง หัวใจ ตับ ไต.','active','2025-08-20 08:48:41','2025-08-20 08:48:41'),(38,'น้ำเกลือต่างๆ IV solution','น้ำเกลือทางการแพทย์ (IV solution) คือสารละลายที่ใช้ฉีดเข้าหลอดเลือดดำ (intravenous) เพื่อทดแทนของเหลวและเกลือแร่ที่ร่างกายสูญเสียไป หรือใช้เพื่อให้ยา. มีหลายประเภท แต่ละชนิดมีส่วนประกอบและวัตถุประสงค์การใช้งานที่แตกต่','active','2025-08-20 08:53:35','2025-08-20 08:53:35'),(39,'กลุ่มยาฮอร์โมน (Hormonal drug group)','ยาที่มีฮอร์โมนเป็นส่วนประกอบ หรือออกฤทธิ์คล้ายฮอร์โมน ซึ่งมีหลากหลายชนิดและวัตถุประสงค์การใช้งานแตกต่างกันไป \r\nประเภทของยาฮอร์โมนได้แก่ ยาฮอร์โมนทดแทน  ยาคุมกำเนิด','active','2025-08-21 08:54:40','2025-08-21 08:54:40'),(40,'กลุ่มโรคไม่ติดต่อเรื้อรัง (Non-Communicable Diseases หรือ NCDs)','คือกลุ่มโรคเรื้อรังที่ไม่ได้เกิดจากการติดเชื้อโรค แต่มีสาเหตุมาจากปัจจัยทางพันธุกรรม สรีรวิทยา สิ่งแวดล้อม และพฤติกรรมในการดำเนินชีวิต','active','2025-08-22 06:48:55','2025-08-22 08:19:19');
